    yypParser: *Parser,
    /// Number of the rule by which to reduce
    yyruleno: usize,
    /// Lookahead token, or YYNOCODE if none
    yyLookahead: YYCODETYPE,
    /// Value of the lookahead token */
    yyLookaheadToken: YY_TOKEN_TYPE
