            (yymsp - 1)[1].minor.@"*Forms".deinit(allocator);
            allocator.destroy((yymsp - 1)[1].minor.@"*Forms");
// #line 1128 src/edn/edn.zig
            (yymsp - 1)[1].minor.@"[]Form" = yylhsminor.@"[]Form";
