        => {
// #line 0 src/edn/edn.zy
            // #line 211 src/edn/edn.zy

            if ((yymsp - 1)[1].minor.@"?Form") |form| {
            errdefer form.deinit(allocator);
            try (yymsp - 2)[1].minor.@"*Forms".append(allocator, form);
            }
// #line 1141 src/edn/edn.zig
        },
        2, // forms ::= form
        => {
// #line 0 src/edn/edn.zy
            // #line 218 src/edn/edn.zy

            errdefer if ((yymsp - 1)[1].minor.@"?Form") |form| form.deinit(allocator);
